
package com.personal.assistant.module.financeplanning.service;
import com.fasterxml.jackson.databind.ObjectMapper;import com.personal.assistant.common.exception.*;import com.personal.assistant.module.financeplanning.dto.FinancePlanningRequests.*;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import java.math.*;import java.sql.Timestamp;import java.time.*;import java.util.*;
@Service public class FinancePlanningService{private final JdbcTemplate jdbc;private final ObjectMapper json;public FinancePlanningService(JdbcTemplate jdbc,ObjectMapper json){this.jdbc=jdbc;this.json=json;}
 public List<Map<String,Object>>budgets(Long uid,String periodKey){String sql="select b.*,c.category_name,coalesce((select sum(t.amount) from finance_transaction t where t.user_id=b.user_id and t.direction='EXPENSE' and (b.category_id is null or t.category_id=b.category_id) and to_char(t.transaction_time,"+(periodKey!=null&&periodKey.length()==4?"'YYYY'":"'YYYY-MM'")+")=b.period_key),0) spent from finance_budget b left join finance_category c on c.id=b.category_id and c.user_id=b.user_id where b.user_id=?"+(periodKey==null?"":" and b.period_key=?")+" order by b.period_key desc";Object[]args=periodKey==null?new Object[]{uid}:new Object[]{uid,periodKey};return jdbc.queryForList(sql,args).stream().map(this::budgetView).toList();}
 @Transactional public Long saveBudget(Long uid,Budget r){if(!Set.of("MONTHLY","YEARLY").contains(r.periodType()))throw validation("预算周期不支持");if(r.categoryId()!=null)owned("finance_category",uid,r.categoryId());List<Long>ids=jdbc.query("select id from finance_budget where user_id=? and period_type=? and period_key=? and category_id is not distinct from ?",(rs,n)->rs.getLong(1),uid,r.periodType(),r.periodKey(),r.categoryId());int alert=r.alertPercent()==null?80:r.alertPercent();if(!ids.isEmpty()){jdbc.update("update finance_budget set amount=?,alert_percent=?,updated_at=now() where id=? and user_id=?",r.amount(),alert,ids.get(0),uid);return ids.get(0);}return jdbc.queryForObject("insert into finance_budget(user_id,period_type,period_key,category_id,amount,alert_percent,created_at,updated_at) values(?,?,?,?,?,?,now(),now()) returning id",Long.class,uid,r.periodType(),r.periodKey(),r.categoryId(),r.amount(),alert);}
 public List<Map<String,Object>>snapshots(Long uid){return jdbc.queryForList("select *,total_assets-total_liabilities net_worth from finance_net_worth_snapshot where user_id=? order by snapshot_date",uid);}@Transactional public Long saveSnapshot(Long uid,Snapshot r){try{return jdbc.queryForObject("insert into finance_net_worth_snapshot(user_id,snapshot_date,total_assets,total_liabilities,details_json,note,created_at) values(?,?,?,?,?,?,now()) on conflict(user_id,snapshot_date) do update set total_assets=excluded.total_assets,total_liabilities=excluded.total_liabilities,details_json=excluded.details_json,note=excluded.note returning id",Long.class,uid,r.snapshotDate(),r.totalAssets(),r.totalLiabilities(),json.writeValueAsString(r.details()==null?Map.of():r.details()),r.note());}catch(Exception e){throw new IllegalStateException(e);}}
 @Transactional public int detectRecurring(Long uid){List<Map<String,Object>>rows=jdbc.queryForList("select merchant,round(avg(amount),2) expected_amount,count(*) cnt,max(transaction_time) last_at from finance_transaction where user_id=? and direction='EXPENSE' and transaction_time>=? and merchant is not null group by merchant having count(*)>=3",uid,Timestamp.valueOf(LocalDateTime.now().minusMonths(6)));int count=0;for(Map<String,Object>r:rows){jdbc.update("insert into finance_recurring_charge(user_id,merchant,charge_type,expected_amount,frequency_days,next_charge_date,active,last_detected_at,created_at) select ?,?,'SUBSCRIPTION',?,30,(?::timestamp + interval '30 day')::date,true,?,now() where not exists(select 1 from finance_recurring_charge where user_id=? and merchant=?)",uid,r.get("merchant"),r.get("expected_amount"),r.get("last_at"),r.get("last_at"),uid,r.get("merchant"));count++;}return count;}public List<Map<String,Object>>recurring(Long uid){return jdbc.queryForList("select * from finance_recurring_charge where user_id=? order by next_charge_date",uid);}
 @Transactional public int scanAnomalies(Long uid){jdbc.update("delete from finance_anomaly where user_id=? and status='OPEN'",uid);int large=jdbc.update("insert into finance_anomaly(user_id,transaction_id,anomaly_type,severity,message,status,detected_at) select user_id,id,'LARGE_EXPENSE','HIGH','大额支出：'||amount,'OPEN',now() from finance_transaction t where user_id=? and direction='EXPENSE' and amount>greatest(1000,(select coalesce(avg(amount),0)*3 from finance_transaction where user_id=t.user_id and direction='EXPENSE')) and transaction_time>=?",uid,Timestamp.valueOf(LocalDateTime.now().minusMonths(3)));int duplicate=jdbc.update("insert into finance_anomaly(user_id,transaction_id,anomaly_type,severity,message,status,detected_at) select a.user_id,a.id,'DUPLICATE_CHARGE','MEDIUM','疑似重复扣款：'||coalesce(a.merchant,'未知商户'),'OPEN',now() from finance_transaction a where a.user_id=? and exists(select 1 from finance_transaction b where b.user_id=a.user_id and b.id<a.id and b.amount=a.amount and coalesce(b.merchant,'')=coalesce(a.merchant,'') and abs(extract(epoch from (a.transaction_time-b.transaction_time)))<259200) and a.transaction_time>=?",uid,Timestamp.valueOf(LocalDateTime.now().minusMonths(3)));return large+duplicate;}public List<Map<String,Object>>anomalies(Long uid){return jdbc.queryForList("select * from finance_anomaly where user_id=? order by detected_at desc",uid);}
 @Transactional public Long reconcile(Long uid,Reconcile r){owned("finance_transaction",uid,r.sourceTransactionId());owned("finance_transaction",uid,r.targetTransactionId());return jdbc.queryForObject("insert into finance_reconciliation(user_id,source_transaction_id,target_transaction_id,relation_type,created_at) values(?,?,?,?,now()) returning id",Long.class,uid,r.sourceTransactionId(),r.targetTransactionId(),r.relationType().toUpperCase());}
 public List<Map<String,Object>>templates(Long uid){return jdbc.queryForList("select id,name,platform,mapping_json,created_at,updated_at from finance_import_template where user_id=? order by name",uid);}@Transactional public Long saveTemplate(Long uid,Template r){try{return jdbc.queryForObject("insert into finance_import_template(user_id,name,platform,mapping_json,created_at,updated_at) values(?,?,?,?,now(),now()) on conflict(user_id,name) do update set platform=excluded.platform,mapping_json=excluded.mapping_json,updated_at=now() returning id",Long.class,uid,r.name(),r.platform().toUpperCase(),json.writeValueAsString(r.mapping()));}catch(Exception e){throw new IllegalStateException(e);}}
 @Transactional public void repairRaw(Long uid,Long rowId,RawRepair r){Integer count=jdbc.queryForObject("select count(*) from finance_raw_transaction x join finance_import_batch b on b.id=x.batch_id where x.id=? and b.user_id=?",Integer.class,rowId,uid);if(count==null||count==0)throw new BusinessException(ErrorCode.NOT_FOUND,"错误行不存在");jdbc.update("update finance_raw_transaction set transaction_time=?,merchant=?,description=?,direction=?,amount=?,category_id=?,validation_error=null where id=?",r.transactionTime(),r.merchant(),r.description(),r.direction(),r.amount(),r.categoryId(),rowId);}
 private Map<String,Object>budgetView(Map<String,Object>row){Map<String,Object>x=new LinkedHashMap<>(row);BigDecimal amount=(BigDecimal)row.get("amount"),spent=(BigDecimal)row.get("spent");x.put("usagePercent",amount.signum()==0?BigDecimal.ZERO:spent.multiply(BigDecimal.valueOf(100)).divide(amount,1,RoundingMode.HALF_UP));x.put("overBudget",spent.compareTo(amount)>0);return x;}private void owned(String table,Long uid,Long id){Integer count=jdbc.queryForObject("select count(*) from "+table+" where id=? and user_id=?",Integer.class,id,uid);if(count==null||count==0)throw new BusinessException(ErrorCode.NOT_FOUND,"关联记录不存在");}private BusinessException validation(String m){return new BusinessException(ErrorCode.VALIDATION_ERROR,m);}}
